if (mode < OS_ALIGN_1STAR || mode > OS_ALIGN_NSTAR ||
    (mode == OS_ALIGN_1STAR && n < 1) ||
    (mode == OS_ALIGN_2STAR && n < 2) ||
    (mode == OS_ALIGN_3STAR && n < 3) ||
    (mode == OS_ALIGN_NSTAR && n < 3)) {
